// --- atfdb.FieldId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void atfdb::value_Print(const atfdb::FieldId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- atfdb.FieldId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool atfdb::value_SetStrptrMaybe(atfdb::FieldId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 2: {
            switch (u64(algo::ReadLE16(rhs.elems))) {
                case LE_STR2('n','s'): {
                    value_SetEnum(parent,atfdb_FieldId_ns); ret = true; break;
                }
            }
            break;
        }
        case 3: {
            switch (u64(algo::ReadLE16(rhs.elems))|(u64(rhs[2])<<16)) {
                case LE_STR3('a','g','e'): {
                    value_SetEnum(parent,atfdb_FieldId_age); ret = true; break;
                }
                case LE_STR3('v','a','r'): {
                    value_SetEnum(parent,atfdb_FieldId_var); ret = true; break;
                }
            }
            break;
        }
        case 4: {
            switch (u64(algo::ReadLE32(rhs.elems))) {
                case LE_STR4('b','u','r','n'): {
                    value_SetEnum(parent,atfdb_FieldId_burn); ret = true; break;
                }
                case LE_STR4('c','o','l','d'): {
                    value_SetEnum(parent,atfdb_FieldId_cold); ret = true; break;
                }
                case LE_STR4('r','e','a','d'): {
                    value_SetEnum(parent,atfdb_FieldId_read); ret = true; break;
                }
            }
            break;
        }
        case 5: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(rhs[4])<<32)) {
                case LE_STR5('b','u','i','l','d'): {
                    value_SetEnum(parent,atfdb_FieldId_build); ret = true; break;
                }
                case LE_STR5('c','i','j','o','b'): {
                    value_SetEnum(parent,atfdb_FieldId_cijob); ret = true; break;
                }
                case LE_STR5('v','a','l','u','e'): {
                    value_SetEnum(parent,atfdb_FieldId_value); ret = true; break;
                }
            }
            break;
        }
        case 6: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(algo::ReadLE16(rhs.elems+4))<<32)) {
                case LE_STR6('c','i','t','e','s','t'): {
                    value_SetEnum(parent,atfdb_FieldId_citest); ret = true; break;
                }
                case LE_STR6('c','o','s','t','m','b'): {
                    value_SetEnum(parent,atfdb_FieldId_costmb); ret = true; break;
                }
                case LE_STR6('f','i','l','t','e','r'): {
                    value_SetEnum(parent,atfdb_FieldId_filter); ret = true; break;
                }
                case LE_STR6('m','s','g','d','i','r'): {
                    value_SetEnum(parent,atfdb_FieldId_msgdir); ret = true; break;
                }
                case LE_STR6('r','e','m','o','v','e'): {
                    value_SetEnum(parent,atfdb_FieldId_remove); ret = true; break;
                }
                case LE_STR6('t','a','r','g','e','t'): {
                    value_SetEnum(parent,atfdb_FieldId_target); ret = true; break;
                }
                case LE_STR6('v','a','r','d','i','r'): {
                    value_SetEnum(parent,atfdb_FieldId_vardir); ret = true; break;
                }
            }
            break;
        }
        case 7: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(algo::ReadLE16(rhs.elems+4))<<32)|(u64(rhs[6])<<48)) {
                case LE_STR7('a','m','c','t','e','s','t'): {
                    value_SetEnum(parent,atfdb_FieldId_amctest); ret = true; break;
                }
                case LE_STR7('c','o','m','m','e','n','t'): {
                    value_SetEnum(parent,atfdb_FieldId_comment); ret = true; break;
                }
                case LE_STR7('i','f','i','l','t','e','r'): {
                    value_SetEnum(parent,atfdb_FieldId_ifilter); ret = true; break;
                }
                case LE_STR7('p','a','c','k','a','g','e'): {
                    value_SetEnum(parent,atfdb_FieldId_package); ret = true; break;
                }
                case LE_STR7('s','a','n','d','b','o','x'): {
                    value_SetEnum(parent,atfdb_FieldId_sandbox); ret = true; break;
                }
                case LE_STR7('t','e','s','t','e','n','v'): {
                    value_SetEnum(parent,atfdb_FieldId_testenv); ret = true; break;
                }
                case LE_STR7('t','i','m','e','o','u','t'): {
                    value_SetEnum(parent,atfdb_FieldId_timeout); ret = true; break;
                }
            }
            break;
        }
        case 8: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('c','o','m','p','t','e','s','t'): {
                    value_SetEnum(parent,atfdb_FieldId_comptest); ret = true; break;
                }
                case LE_STR8('c','o','v','e','r','a','g','e'): {
                    value_SetEnum(parent,atfdb_FieldId_coverage); ret = true; break;
                }
                case LE_STR8('f','a','i','l','f','a','s','t'): {
                    value_SetEnum(parent,atfdb_FieldId_failfast); ret = true; break;
                }
                case LE_STR8('m','e','m','c','h','e','c','k'): {
                    value_SetEnum(parent,atfdb_FieldId_memcheck); ret = true; break;
                }
                case LE_STR8('s','l','o','w','o','n','l','y'): {
                    value_SetEnum(parent,atfdb_FieldId_slowonly); ret = true; break;
                }
                case LE_STR8('t','e','s','t','n','a','m','e'): {
                    value_SetEnum(parent,atfdb_FieldId_testname); ret = true; break;
                }
                case LE_STR8('u','n','i','t','t','e','s','t'): {
                    value_SetEnum(parent,atfdb_FieldId_unittest); ret = true; break;
                }
            }
            break;
        }
        case 9: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('f','u','z','z','s','t','r','a'): {
                    if (memcmp(rhs.elems+8,"t",1)==0) { value_SetEnum(parent,atfdb_FieldId_fuzzstrat); ret = true; break; }
                    break;
                }
                case LE_STR8('r','e','i','n','s','t','a','l'): {
                    if (memcmp(rhs.elems+8,"l",1)==0) { value_SetEnum(parent,atfdb_FieldId_reinstall); ret = true; break; }
                    break;
                }
                case LE_STR8('s','t','a','b','l','e','f','l'): {
                    if (memcmp(rhs.elems+8,"d",1)==0) { value_SetEnum(parent,atfdb_FieldId_stablefld); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 10: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('m','a','t','c','h','o','r','d'): {
                    if (memcmp(rhs.elems+8,"er",2)==0) { value_SetEnum(parent,atfdb_FieldId_matchorder); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 12: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('u','n','s','t','a','b','l','e'): {
                    if (memcmp(rhs.elems+8,"attr",4)==0) { value_SetEnum(parent,atfdb_FieldId_unstableattr); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 17: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('t','e','s','t','_','g','s','y'): {
                    if (memcmp(rhs.elems+8,"mbol_char",9)==0) { value_SetEnum(parent,atfdb_FieldId_test_gsymbol_char); ret = true; break; }
                    if (memcmp(rhs.elems+8,"mbol_pkey",9)==0) { value_SetEnum(parent,atfdb_FieldId_test_gsymbol_pkey); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 19: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('t','e','s','t','_','g','s','y'): {
                    if (memcmp(rhs.elems+8,"mbol_strptr",11)==0) { value_SetEnum(parent,atfdb_FieldId_test_gsymbol_strptr); ret = true; break; }
                    break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- atfdb.FieldId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void atfdb::value_SetStrptr(atfdb::FieldId& parent, algo::strptr rhs, atfdb_FieldIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- atfdb.FieldId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool atfdb::value_ReadStrptrMaybe(atfdb::FieldId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

// --- atfdb.FieldId..ReadStrptrMaybe
// Read fields of atfdb::FieldId from an ascii string.
// The format of the string is the format of the atfdb::FieldId's only field
bool atfdb::FieldId_ReadStrptrMaybe(atfdb::FieldId &parent, algo::strptr in_str) {
    bool retval = true;
    retval = retval && value_ReadStrptrMaybe(parent, in_str);
    return retval;
}

